/// Narrow typed boundary between Flutter session management and the native
/// OpenMLS client. The concrete implementation is generated by
/// flutter_rust_bridge; credentials cross this boundary once during adoption.
abstract interface class MlsSessionBridge {
  Future<void> open({
    required String baseUrl,
    required String userId,
    required String deviceId,
    required String accessToken,
    required String refreshToken,
  });

  /// Returns only the short-lived access token. The refresh token must never
  /// be returned to Dart after [open] succeeds.
  Future<String> accessTokenSnapshot();

  /// Rotates the session inside Rust and returns only the new access token.
  Future<String> refreshSession();

  Future<void> logout();

  /// Releases the opaque native client handle without changing server state.
  Future<void> close();
}
